    {
        "series": [
            {
                "name": "民間最終消費支出",
                "code": "12",
                "data": [{"date": "2024-Q1", "value": 0.5}, ...]
            },
            {
                "name": "民間企業設備",
                "code": "16",
                "data": [{"date": "2024-Q1", "value": 1.2}, ...]
            }
